--- a/src/server.rs
+++ b/src/server.rs
@@ -498,6 +498,14 @@ async fn attend(
     let ev = store.attend(&name, spec)?;
+    // Look at the page once, so the reply can say where the card really shows.
+    let anchored = match ev.args.as_ref().and_then(|a| a["anchor"]["selector"].as_str()) {
+        Some(sel) => match snapshot(&app, &name).await {
+            Ok(snap) => Some(!snap.missing.iter().any(|m| m.ends_with(sel))),
+            Err(_) => None,
+        },
+        None => Some(true),
+    };
     Ok(Json(json!(ev)))

--- a/src/main.rs
+++ b/src/main.rs
@@ -656,8 +656,13 @@ fn report(ev: Value) -> Result<(), String> {
-        "attention" => format!("asked {} {:?}; it shows on the page{}. Answers arrive in `jelly inbox`", s(&ev["args"]["id"]), s(&ev["args"]["title"]),
-            ev["args"]["anchor"]["selector"].as_str().map(|a| format!(" below {a}")).unwrap_or_default()),
+        "attention" => {
+            let at = ev["args"]["anchor"]["selector"].as_str();
+            let place = match (at, ev["anchored"].as_bool()) {
+                (Some(a), Some(true)) => format!("it shows below {a}"),
+                (Some(a), Some(false)) => format!("{a} matches nothing on the page, so it shows at the top"),
+                (Some(a), None) => format!("could not check {a}: no browser"),
+                (None, _) => "it shows at the top".into(),
+            };
+            format!("asked {} {:?}; {place}", s(&ev["args"]["id"]), s(&ev["args"]["title"]))
+        }

